		float Usm64_allFunctionLibrary::sss_diffusion_profile(const float world_dist, const float falloff)
		{
			TEXT("");
			TEXT("\n    Burley diffusion profile: S(r) = A*exp(-r/d)/r + A*exp(-r/(3d))/(3r)\n    \n    This is a physically-based approximation of light diffusion through\n    translucent materials. The dual-lobe structure captures both near-surface\n    and deep subsurface scattering.\n    \n    Parameters:\n    - world_dist: Distance from sample point in world units\n    - falloff: Diffusion falloff (smaller = tighter scatter, larger = wider)\n    \n    Returns: Scattering weight [0-inf], typically normalized by sum of weights\n    \n    Example usage:\n    ```\n    let dist = length(sample_pos - center_pos)\n    let weight = sss_diffusion_profile(dist, 0.5)\n    accumulated_color = accumulated_color + sample_color * weight\n    ```\n    ");
			TEXT("");
			auto s = (3.670000f * falloff);
			auto safe_dist = (world_dist + 0.001000f);
			auto near_lobe = (FMath::Exp(((-safe_dist) * s)) / safe_dist);
			auto far_lobe = (FMath::Exp((((-safe_dist) * s) / 3.000000f)) / ((3.000000f * safe_dist)));
			return (near_lobe + far_lobe);
		}

		FVector Usm64_allFunctionLibrary::sss_transmittance(const float thickness, const float absorption_r, const float absorption_g, const float absorption_b)
		{
			TEXT("");
			TEXT("\n    Beer-Lambert law: I = I0 * exp(-absorption * thickness)\n    \n    Models how light is absorbed as it travels through a material.\n    Different wavelengths (RGB) are absorbed at different rates,\n    creating the characteristic color of transmitted light.\n    \n    Parameters:\n    - thickness: Material thickness (from thickness map or geometry)\n    - absorption_r/g/b: Per-channel absorption coefficients\n      Higher values = more absorption = less transmission\n    \n    Returns: Vec3 transmittance factor to multiply with light color\n    \n    Example usage:\n    ```\n    let thickness = sample(thickness_map, uv).r\n    let transmit = sss_transmittance(thickness, 2.0, 3.0, 4.0)\n    let transmitted_light = light_color * transmit * backlight_intensity\n    ```\n    \n    Typical absorption values:\n    - Skin: R=2.0, G=3.0, B=4.0 (red penetrates deeper)\n    - Wax: R=1.5, G=1.8, B=2.0\n    - Marble: R=0.5, G=0.6, B=0.7\n    ");
			TEXT("");
			auto r = FMath::Exp(((-thickness) * absorption_r));
			auto g = FMath::Exp(((-thickness) * absorption_g));
			auto b = FMath::Exp(((-thickness) * absorption_b));
			return FVector(r, g, b);
		}

		float Usm64_allFunctionLibrary::sss_wrap_lighting(const float n_dot_l, const float wrap_amount)
		{
			TEXT("");
			TEXT("\n    Wrap lighting softens the diffuse terminator by allowing light to\n    ");
			wrap;
			around;
			TEXT(" surface edges. This simulates subsurface scattering's\n    effect of light penetrating and scattering within the material.\n    \n    Parameters:\n    - n_dot_l: Standard Lambert term (dot(normal, light_dir))\n    - wrap_amount: Wrap factor [0-1]\n      0.0 = standard Lambert (hard terminator)\n      0.5 = moderate wrap (good for skin)\n      1.0 = full wrap (very soft, good for thin materials)\n    \n    Returns: Modified diffuse term [0-1]\n    \n    Example usage:\n    ```\n    let n_dot_l = dot(world_normal, light_dir)\n    let wrapped = sss_wrap_lighting(n_dot_l, 0.5)\n    let diffuse = albedo * light_color * wrapped\n    ```\n    ");
			TEXT("");
			return FMath::Max((((n_dot_l + wrap_amount)) / ((1.000000f + wrap_amount))), 0.000000f);
		}

		float Usm64_allFunctionLibrary::sss_translucency(const float n_dot_l, const float translucency, const float power)
		{
			TEXT("");
			TEXT("\n    Translucency effect for thin materials like leaves, ears, fingers.\n    When light hits the back of the surface, some passes through,\n    creating a characteristic glow.\n    \n    Parameters:\n    - n_dot_l: dot(normal, light_dir) - can be negative for backfaces\n    - translucency: Overall translucency strength [0-1]\n    - power: Falloff exponent (1.0 = linear, 2.0+ = tighter hotspot)\n    \n    Returns: Translucency contribution [0-1]\n    \n    Example usage:\n    ```\n    let n_dot_l = dot(world_normal, light_dir)\n    let translucent = sss_translucency(n_dot_l, 0.8, 2.0)\n    let backlight = light_color * translucent * thickness_factor\n    ```\n    \n    Typical values:\n    - Skin (ears, nose): translucency=0.5, power=2.0\n    - Leaves: translucency=0.8, power=1.5\n    - Thin fabric: translucency=0.6, power=2.5\n    ");
			TEXT("");
			auto backface_factor = FMath::Clamp((-n_dot_l), 0.000000f, 1.000000f);
			auto shaped = FMath::Pow(backface_factor, power);
			return (shaped * translucency);
		}

		FVector Usm64_allFunctionLibrary::skin_scattering(const float thickness, const float epidermis_scatter, const float dermis_scatter, const float blood_absorption)
		{
			TEXT("");
			TEXT("\n    Two-layer skin model with epidermis (outer) and dermis (inner) layers.\n    Accounts for hemoglobin absorption in blood vessels.\n    \n    Skin structure:\n    - Epidermis: Thin outer layer, scatters all wavelengths equally\n    - Dermis: Thicker inner layer with blood vessels\n    - Blood: Absorbs green/blue, transmits red (creates red glow)\n    \n    Parameters:\n    - thickness: Normalized thickness [0-1] from thickness map\n    - epidermis_scatter: Epidermis scattering distance (typically 0.5-1.0)\n    - dermis_scatter: Dermis scattering distance (typically 2.0-4.0)\n    - blood_absorption: Blood absorption strength (typically 3.0-5.0)\n    \n    Returns: RGB color modulation for scattered light\n    \n    Example usage:\n    ```\n    let thickness = sample(thickness_map, uv).r\n    let skin_color = skin_scattering(thickness, 0.8, 3.0, 4.0)\n    let sss_result = blurred_irradiance * skin_color * sss_strength\n    ```\n    ");
			TEXT("");
			auto epidermis_factor = FMath::Exp((((-thickness) / epidermis_scatter) * 2.000000f));
			auto dermis_r = FMath::Exp((((-thickness) / dermis_scatter) * 2.000000f));
			auto dermis_g = FMath::Exp((((-thickness) / dermis_scatter) * 3.000000f));
			auto dermis_b = FMath::Exp((((-thickness) / dermis_scatter) * 4.000000f));
			auto blood_factor = (1.000000f - FMath::Exp(((-thickness) * blood_absorption)));
			auto blood_tint_r = 1.000000f;
			auto blood_tint_g = 0.300000f;
			auto blood_tint_b = 0.200000f;
			auto r = ((epidermis_factor * dermis_r) * ((1.000000f + (blood_factor * blood_tint_r))));
			auto g = ((epidermis_factor * dermis_g) * ((1.000000f + (blood_factor * blood_tint_g))));
			auto b = ((epidermis_factor * dermis_b) * ((1.000000f + (blood_factor * blood_tint_b))));
			return FVector(r, g, b);
		}

		FVector Usm64_allFunctionLibrary::foliage_scattering(const float thickness, const float chlorophyll_density, const float translucency)
		{
			TEXT("");
			TEXT("\n    Foliage scattering model accounting for chlorophyll absorption.\n    Chlorophyll strongly absorbs red and blue, transmits green/yellow.\n    \n    Creates the characteristic green glow when light passes through leaves.\n    \n    Parameters:\n    - thickness: Leaf thickness [0-1] - thinner leaves transmit more\n    - chlorophyll_density: Chlorophyll concentration [0-1]\n      Higher density = more green, less red/blue transmission\n    - translucency: Overall translucency strength [0-1]\n    \n    Returns: RGB transmission color\n    \n    Example usage:\n    ```\n    let thickness = sample(thickness_map, uv).r\n    let foliage_color = foliage_scattering(thickness, 0.7, 0.8)\n    let transmitted = backlight * foliage_color\n    ```\n    \n    Typical values:\n    - Fresh leaves: chlorophyll=0.7, translucency=0.8\n    - Dry leaves: chlorophyll=0.3, translucency=0.5\n    - Thick leaves: thickness=0.8, chlorophyll=0.8\n    ");
			TEXT("");
			auto red_absorption = (3.000000f * chlorophyll_density);
			auto green_absorption = (0.500000f * chlorophyll_density);
			auto blue_absorption = (2.500000f * chlorophyll_density);
			auto r = (FMath::Exp(((-thickness) * red_absorption)) * translucency);
			auto g = (FMath::Exp(((-thickness) * green_absorption)) * translucency);
			auto b = (FMath::Exp(((-thickness) * blue_absorption)) * translucency);
			auto green_boost = (1.000000f + (((1.000000f - thickness)) * 0.500000f));
			return FVector(r, (g * green_boost), b);
		}

		FVector Usm64_allFunctionLibrary::wax_scattering(const float thickness, const float scatter_distance, const float warmth)
		{
			TEXT("");
			TEXT("\n    Wax scattering model with characteristic warm glow.\n    Wax has relatively uniform scattering across wavelengths,\n    with slight warm bias (yellow/orange tint).\n    \n    Parameters:\n    - thickness: Wax thickness [0-1]\n    - scatter_distance: Scattering distance (typically 1.5-3.0)\n      Lower = tighter scatter, higher = more diffuse\n    - warmth: Warm color bias [0-1]\n      0.0 = neutral white, 1.0 = warm orange glow\n    \n    Returns: RGB transmission color\n    \n    Example usage:\n    ```\n    let thickness = sample(thickness_map, uv).r\n    let wax_color = wax_scattering(thickness, 2.0, 0.6)\n    let candle_glow = backlight * wax_color * glow_intensity\n    ```\n    \n    Typical values:\n    - White candle: warmth=0.3, scatter_distance=2.0\n    - Colored wax: warmth=0.5, scatter_distance=2.5\n    - Thin wax: thickness=0.3, scatter_distance=1.5\n    ");
			TEXT("");
			auto base_scatter = FMath::Exp(((-thickness) / scatter_distance));
			auto warm_r = (1.000000f + (warmth * 0.300000f));
			auto warm_g = (1.000000f + (warmth * 0.150000f));
			auto warm_b = (1.000000f - (warmth * 0.200000f));
			auto r = (base_scatter * warm_r);
			auto g = (base_scatter * warm_g);
			auto b = (base_scatter * warm_b);
			return FVector(r, g, b);
		}

		FVector Usm64_allFunctionLibrary::marble_scattering(const float thickness, const float crystallinity, const float coolness)
		{
			TEXT("");
			TEXT("\n    Marble scattering model with cool, crystalline appearance.\n    Marble has complex internal structure with varying translucency.\n    \n    Parameters:\n    - thickness: Stone thickness [0-1]\n    - crystallinity: Crystal structure density [0-1]\n      Higher = more structured, less uniform transmission\n    - coolness: Cool color bias [0-1]\n      0.0 = neutral, 1.0 = cool blue/cyan tint\n    \n    Returns: RGB transmission color\n    \n    Example usage:\n    ```\n    let thickness = sample(thickness_map, uv).r\n    let marble_color = marble_scattering(thickness, 0.6, 0.4)\n    let transmitted = backlight * marble_color\n    ```\n    \n    Typical values:\n    - White marble: coolness=0.3, crystallinity=0.5\n    - Colored marble: coolness=0.5, crystallinity=0.7\n    - Thin slabs: thickness=0.4, crystallinity=0.6\n    ");
			TEXT("");
			auto base_scatter = FMath::Exp(((-thickness) * ((1.500000f + (crystallinity * 0.500000f)))));
			auto crystal_r = (1.000000f - (crystallinity * 0.100000f));
			auto crystal_g = 1.000000f;
			auto crystal_b = (1.000000f + (crystallinity * 0.100000f));
			auto cool_r = (1.000000f - (coolness * 0.200000f));
			auto cool_g = (1.000000f + (coolness * 0.100000f));
			auto cool_b = (1.000000f + (coolness * 0.300000f));
			auto r = ((base_scatter * crystal_r) * cool_r);
			auto g = ((base_scatter * crystal_g) * cool_g);
			auto b = ((base_scatter * crystal_b) * cool_b);
			return FVector(r, g, b);
		}

		float Usm64_allFunctionLibrary::sss_rim_lighting(const FVector normal, const FVector view_dir, const FVector light_dir, const float rim_power, const float rim_intensity)
		{
			TEXT("");
			TEXT("\n    Rim lighting for SSS materials enhances translucency perception.\n    At grazing angles, more light scatters toward the viewer,\n    creating a characteristic glow around edges.\n    \n    Parameters:\n    - normal: Surface normal (world space, normalized)\n    - view_dir: Direction to camera (world space, normalized)\n    - light_dir: Direction to light (world space, normalized)\n    - rim_power: Falloff exponent (typically 2.0-4.0)\n      Higher = tighter rim, lower = broader glow\n    - rim_intensity: Brightness multiplier (typically 0.1-0.5)\n    \n    Returns: Rim contribution to add to final color\n    \n    Example usage:\n    ```\n    let rim = sss_rim_lighting(world_normal, view_dir, light_dir, 3.0, 0.2)\n    let rim_color = light_color * rim\n    final_color = final_color + rim_color\n    ```\n    ");
			TEXT("");
			auto n_dot_v = FMath::Max(FVector::DotProduct(normal, view_dir), 0.000000f);
			auto rim_factor = FMath::Pow((1.000000f - n_dot_v), rim_power);
			auto n_dot_l = FVector::DotProduct(normal, light_dir);
			auto backlight_boost = FMath::SmoothStep((-0.500000f), 0.500000f, (-n_dot_l));
			return ((rim_factor * rim_intensity) * ((1.000000f + backlight_boost)));
		}

		FVector Usm64_allFunctionLibrary::bloom_extract(const FVector color, const float threshold, const float soft_knee)
		{
			auto brightness = FVector::DotProduct(color, FVector(0.212600f, 0.715200f, 0.072200f));
			auto knee = (threshold * soft_knee);
			auto soft = ((brightness - threshold) + knee);
			auto soft_clamped = FMath::Clamp(soft, 0.000000f, (2.000000f * knee));
			auto contribution = ((brightness > (threshold - knee)) ? ((soft_clamped * soft_clamped) / (((4.000000f * knee) + 0.000010f))) : 0.000000f);
			auto extracted = ((color * contribution) / FMath::Max(brightness, 0.000100f));
			return extracted;
		}

