			auto normal_diff = (1.000000f - FVector::DotProduct(normal_center, normal_avg));
			auto normal_edge = ((normal_diff > normal_threshold) ? 1.000000f : 0.000000f);
			auto edge_strength = (FMath::Max(depth_edge, normal_edge) * outline_thickness);
