			auto medium_detail = Usm64_allFunctionLibrary::fbm2(((cloud_uv * 2.500000f) + FVector2D((seed * 1.300000f), (seed * 0.700000f))), 4);
			auto fine_detail = Usm64_allFunctionLibrary::fbm2(((cloud_uv * 6.000000f) + FVector2D((seed * 2.100000f), (seed * 1.900000f))), 5);
			auto cloud_base = (((large_clouds * 0.500000f) + (medium_detail * 0.300000f)) + (fine_detail * 0.200000f));
			auto cloud_mask = FMath::SmoothStep((1.000000f - coverage), ((1.000000f - coverage) + 0.100000f), cloud_base);
