		int64 Usm64_allFunctionLibrary::weighted_random(const TArray<float> weights)
		{
			auto total_weight = 0.000000f;
			auto i = 0;
			while ((i < weights.Num()))
			{
				total_weight = (total_weight + weights[i]);
				i = (i + 1);
			}
			auto rand_val = (FMath::FRand() * total_weight);
			auto cumulative = 0.000000f;
			auto j = 0;
			while ((j < weights.Num()))
			{
				cumulative = (cumulative + weights[j]);
				if ((rand_val <= cumulative))
				{
					return j;
				}
				j = (j + 1);
			}
			return (weights.Num() - 1);
		}

